package com.hms.service; import com.hms.dao.AppointmentDao; import com.hms.model.Appointment; import java.sql.SQLException; import java.time.LocalDate; import java.time.LocalTime; import java.util.List; public class AppointmentService{private final AppointmentDao dao;public AppointmentService(AppointmentDao d){dao=d;}public List<Appointment> findAll(String s,LocalDate d)throws SQLException{return dao.findAll(s,d);}public Appointment save(Appointment a)throws SQLException{return dao.save(a);}public void reschedule(int id,LocalDate date,LocalTime time)throws SQLException{dao.reschedule(id,date,time);}public void updateStatus(int id,String s)throws SQLException{dao.updateStatus(id,s);}public void delete(int id)throws SQLException{dao.delete(id);}}
